            <p className="sr-only" id="form-instructions">Fields marked with an asterisk are required.</p>

            <div className="form-field">
              <fieldset aria-describedby="form-instructions">
                <legend>
                  How do you prefer to receive notifications?
                  <span className="required-marker" aria-hidden="true">*</span>
                </legend>

                <div className="radio-option">
                  <input 
                    type="radio" 
                    id="pref-email" 
                    name="notification_pref" 
                    value="Email" 
                    checked={preference === 'Email'}
                    onChange={(e) => setPreference(e.target.value)}
                    required
                  />
                  <label htmlFor="pref-email">Email</label>
                </div>

                <div className="radio-option">
                  <input 
                    type="radio" 
                    id="pref-sms" 
                    name="notification_pref" 
                    value="SMS" 
                    checked={preference === 'SMS'}
                    onChange={(e) => setPreference(e.target.value)}
                    required
                  />
                  <label htmlFor="pref-sms">SMS</label>
                </div>

                <div className="radio-option">
                  <input 
                    type="radio" 
                    id="pref-push" 
                    name="notification_pref" 
                    value="Push Notifications" 
                    checked={preference === 'Push Notifications'}
                    onChange={(e) => setPreference(e.target.value)}
                    required
                  />
                  <label htmlFor="pref-push">Push Notifications</label>
                </div>
              </fieldset>
            </div>

            <button type="submit" className="submit-btn">Save</button>
          </form>
        </main>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<NotificationForm />);
  </script>
</body>
